changeSet.sql:
CREATE OR ALTER TRIGGER trg_answer_attempt_quiz_denorm ON answer_attempt AFTER INSERT, UPDATE, DELETE AS BEGIN DECLARE @AffectedQuizzes TABLE (quiz_id BIGINT);
INSERT INTO @AffectedQuizzes (quiz_id) SELECT DISTINCT tq.quiz_id FROM inserted i INNER JOIN student_attempt sa ON i.student_attempt_id = sa.id INNER JOIN task_quiz tq ON sa.task_id = tq.task_id UNION SELECT DISTINCT tq.quiz_id FROM deleted d INNER JOIN student_attempt sa ON d.student_attempt_id = sa.id INNER JOIN task_quiz tq ON sa.task_id = tq.task_id;
UPDATE q SET q.success_rate = ISNULL(stats.calc_rate, 0.00) FROM quiz q INNER JOIN @AffectedQuizzes aq ON q.id = aq.quiz_id LEFT JOIN ( SELECT tq.quiz_id, CASE WHEN COUNT(aa.id) > 0 THEN CAST( SUM(CASE WHEN aa.is_answer_correct = 1 THEN 1.0 ELSE 0 END) / COUNT(aa.id) * 100 AS DECIMAL(5,2)) ELSE 0.00 END AS calc_rate FROM task_quiz tq INNER JOIN student_attempt sa ON sa.task_id = tq.task_id INNER JOIN answer_attempt aa ON aa.student_attempt_id = sa.id GROUP BY tq.quiz_id ) stats ON q.id = stats.quiz_id; END;
